995	    /// Performs an acceptance check for the provided `operator` by calling
996	    /// [`IErc721Receiver::on_erc721_received`] on the `to` address. The
997	    /// `operator` is generally the address that initiated the token transfer
998	    /// (i.e. `self.vm().msg_sender()`).
999	    ///
1000	    /// The acceptance call is not executed and treated as a no-op if the
1001	    /// target address doesn't contain code (i.e. an EOA). Otherwise, the
1002	    /// recipient must implement [`IErc721Receiver::on_erc721_received`] and
1003	    /// return the acceptance magic value to accept the transfer.
1004	    ///
1005	    /// # Arguments
1006	    ///
1007	    /// * `&mut self` - Write access to the contract's state.
1008	    /// * `operator` - Account to add to the set of authorized operators.
1009	    /// * `from` - Account of the sender.
1010	    /// * `to` - Account of the recipient.
1011	    /// * `token_id` - Token id as a number.
1012	    /// * `data` - Additional data with no specified format, sent in call to
1013	    ///   `to`.
1014	    ///
1015	    /// # Errors
1016	    ///
1017	    /// * [`Error::InvalidReceiver`] - If
1018	    ///   [`IErc721Receiver::on_erc721_received`] hasn't returned its interface
1019	    ///   id or returned an error.
1020	    /// * [`Error::InvalidReceiverWithReason`] - If
1021	    ///   [`IErc721Receiver::on_erc721_received`] reverted with revert data.
1022	    pub fn _check_on_erc721_received(
1023	        &mut self,
1024	        operator: Address,
1025	        from: Address,
1026	        to: Address,
1027	        token_id: U256,
1028	        data: &Bytes,
1029	    ) -> Result<(), Error> {
1030	        if !AddressUtils::has_code(self, to) {
1031	            return Ok(());
1032	        }
1033	
1034	        let receiver = IErc721ReceiverInterface::new(to);
1035	        let call = Call::new_mutating(self);
1036	        let result = receiver.on_erc_721_received(
1037	            self.vm(),
1038	            call,
1039	            operator,
1040	            from,
1041	            token_id,
1042	            data.to_vec().into(),
1043	        );
1044	
1045	        let id = match result {
1046	            Ok(id) => id,
1047	            Err(e) => {
1048	                if let CallError::Revert(ref reason) = e {
1049	                    if !reason.is_empty() {
1050	                        return Err(Error::InvalidReceiverWithReason(
1051	                            InvalidReceiverWithReason {
1052	                                reason: String::from_utf8_lossy(reason)
1053	                                    .to_string(),
1054	                            },
1055	                        ));
1056	                    }
1057	                }
1058	
1059	                // Non-IERC721Receiver implementer.
1060	                return Err(ERC721InvalidReceiver { receiver: to }.into());
1061	            }
1062	        };
1063	
1064	        // Token rejected.
1065	        if id != RECEIVER_FN_SELECTOR {
1066	            return Err(ERC721InvalidReceiver { receiver: to }.into());
1067	        }
1068	
1069	        Ok(())
1070	    }
1071	}
