      32	    /// * [`Error::EmptyCode`] - If the target contract has no code.
      33	    /// * [`Error::FailedCallWithReason`] - If the call to the target contract
      34	    ///   fails with a revert reason or if the call fails for any other reason.
      35	    /// * [`Error::FailedCall`] - If the call to the target contract fails
      36	    ///   without a revert reason.
      37	    pub fn verify_call_result_from_target<T: AsRef<[u8]>>(
      38	        context: &impl HostAccess<Host = VM>,
      39	        target: Address,
